    expires_at: datetime | None = None
    granted_permissions: StringArray | None = None
    # The id for this model
    id: UUID | None = None
    # LastErrorCode is why the last attempt failed, as a stable code rather than provider prose — see the ErrorCode constants. Cleared on success.
    last_error_code: str | None = None
