class SnapshotStatus(str, Enum):
    "Named for the domain rather than called Status: the merged OpenAPI spec is a single namespace shared with every other service, and a bare \"Status\" collided with pgtype.Status there — silently turning this into an integer in the generated clients."
    PENDING = "pending"
    READY = "ready"
    FAILED = "failed"
    UNKNOWN = ""

    @classmethod
    def _missing_(cls, value: object) -> Self:
        return cls.UNKNOWN


