class SubjectType(str, Enum):
    "It is a named type so the generated clients get a real enum rather than a bare string; the member list is mirrored in the Dart SDK's nativeEnums config, because go-swagger cannot carry enum values for a named type (working document §13)."
    PROPERTY = "property"
    HOLDING_ITEM = "holding_item"
    EXTERNAL_REF = "external_ref"
    UNKNOWN = ""

    @classmethod
    def _missing_(cls, value: object) -> Self:
        return cls.UNKNOWN


